/**
 * Open-source notices for the Acknowledgements page. The JSON is generated by scripts/acknowledgements.mjs
 * (run it after changing dependencies, pods, fonts or models); CI fails when it is out of date.
 */
import data from './acknowledgements.json';

export type NoticePlatform = 'macos' | 'windows';

export interface Notice {
  name: string;
  version?: string;
  /** SPDX id where there is one. */
  license: string;
  /** Copyright lines and the full licence text. */
  text: string;
  /** Only in these builds. Omitted when every build ships it. */
  platforms?: NoticePlatform[];
}

export interface NoticeGroup {
  title: string;
  notices: Notice[];
}

const GROUPS = data.groups as NoticeGroup[];

/** The groups for one build, without notices it doesn't ship and without empty groups. */
export function noticeGroups(platform: NoticePlatform): NoticeGroup[] {
  return GROUPS.map((g) => ({ ...g, notices: g.notices.filter((n) => !n.platforms || n.platforms.includes(platform)) })).filter(
    (g) => g.notices.length > 0,
  );
}
